// TH14 bullet vocabulary subset for this card (touhou-bullets.ecl aliases).
// TH14 source type 8 -> target row 480; TH14 source type 18 -> target row 640.
const TH14_RICE: int = 480;
const TH14_BIG_BALL: int = 640;

// TH14 v1.00b st06 midboss wave: MainSub00 (20x Phantom01) + MainSub01 (3x Phantom02).
// Source: st06.ecl.txt 564-577 (entry), 579-591, 976-1001, 1003-1032,
//         1069-1092, 1094-1132. Phantom01_at2 (source 1034-1067) is the HL setDeath
//         callback; the invulnerable training shell never kills these enemies, so it
//         is not triggered (task: no synthetic timed death / no setDeath firing).

const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------- Phantom01_at
// Source 1003-1032: etSprite(8,6), etAim(0), etCount(1,1), etSpeed(3.5,1),
// etEx ANIM a=1 (visual only, birth retraction kept), wait 10,
// diffI(A, 3,30,30,30) volleys of one aimed rice; wait 80 on Easy, 20 otherwise.
async sub phantom01_at() {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 6);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, 3.5fx, 0fx);
    sh_dist(0, -14fx);              // ANIM a=1: position -= 4 * 3.5

    wait(10);
    var shots: int = 30;            // diffI($A, 3, 30, 30, 30)
    var gap: int = 20;
    if global(GVAR_RANK) == RANK_EASY {
        shots = 3;
        gap = 80;
    }
    var i: int = 0;
    while i < shots {
        wait(gap);
        sh_fire(0);
        i = i + 1;
    }
}

// ------------------------------------------------------------------ Phantom01
// Source 976-1001: boxes 28/16 -> r14/r8, drop omitted, @Phantom01_at async,
// moveVel(2.9452431 rad = 168.75 deg, 3.0), moveCircleRel(RANDRAD, 1 deg,
// -1.1780972, 0), moveCircleRelTime(80, mode0, keep omega, r -> 32, d -> 0),
// wait 60, moveAngleTime(120, mode7, 3 deg/frame), wait 60, idle loop.
// Target has no ABS+REL composition, so both layers are integrated explicitly and
// written with move_to(0,...) each frame (circular-motion recipe).
async sub phantom01() {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    spawn phantom01_at();

    var ax: fx = $self_x;                       // ABS layer position
    var ay: fx = $self_y;
    var ang: angle = 30720bam;                  // 168.75 deg
    var spd: fx = 3fx;
    var theta: angle = rand(65536) as angle;    // %RANDRAD
    var r0: fx = -1.1780972fx;
    var r: fx = r0;                             // REL circle radius
    move_to(0, ax + r * cos(theta), ay + r * sin(theta), EASE_LINEAR);
    wait(1);

    var f: int = 1;
    loop {
        theta = theta + 1deg;                   // moveCircleRel omega
        if f <= 80 {
            r = r0 + (32fx - r0) * (f as fx) / 80fx;
        }
        if f >= 61 && f <= 180 {
            ang = ang + 3deg;                   // moveAngleTime mode7
        }
        ax = ax + spd * cos(ang);
        ay = ay + spd * sin(ang);
        move_to(0, ax + r * cos(theta), ay + r * sin(theta), EASE_LINEAR);
        wait(1);
        f = f + 1;
    }
}

// ---------------------------------------------------------------- Phantom02_at
// Source 1094-1132: etSprite(18,6), etAim(3) fixed ring,
// etCount(4/8/8/8, 1), etAngle(%RANDRAD, pi/4), etSpeed(2.8/4.0/4.5/5.0, ...),
// etEx ANIM a=1 (visual only, birth retraction kept), wait 20,
// diffI(A, 3, 3, 5, 7) volleys every 40. RANDRAD is read once at config time.
async sub phantom02_at() {
    var ways: int = 8;
    var spd: fx = 4fx;
    if global(GVAR_RANK) == RANK_EASY {
        ways = 4;
        spd = 2.8fx;
    }
    if global(GVAR_RANK) == RANK_HARD {
        spd = 4.5fx;
    }
    if global(GVAR_RANK) == RANK_LUNATIC {
        spd = 5fx;
    }
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_angle(0, rand(65536) as angle, 45deg);
    sh_speed(0, spd, 0fx);
    sh_dist(0, 0fx - spd * 4fx);    // ANIM a=1: position -= 4 * speed

    wait(20);
    var vol: int = 3;               // diffI($A, 3, 3, 5, 7)
    if global(GVAR_RANK) == RANK_HARD {
        vol = 5;
    }
    if global(GVAR_RANK) == RANK_LUNATIC {
        vol = 7;
    }
    var i: int = 0;
    while i < vol {
        sh_fire(0);
        wait(40);
        i = i + 1;
    }
}

// ------------------------------------------------------------------ Phantom02
// Source 1069-1092: boxes 28/16 -> r14/r8, drop omitted, @Phantom02_at async,
// moveCircleRel(RANDRAD, 2 deg, 0, 0), moveCircleRelTime(80, mode0, keep omega,
// r -> 32), wait 80, wait 80, moveVel(%ANGLE_PLAYER, 0), moveSpeedTime(120,
// mode0, 1.0), wait 60, idle loop.
async sub phantom02() {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    spawn phantom02_at();

    var ax: fx = $self_x;                       // ABS layer position
    var ay: fx = $self_y;
    var ang: angle = 0deg;
    var spd: fx = 0fx;
    var theta: angle = rand(65536) as angle;    // %RANDRAD
    var r: fx = 0fx;
    move_to(0, ax, ay, EASE_LINEAR);
    wait(1);

    var f: int = 1;
    loop {
        theta = theta + 2deg;                   // moveCircleRel omega
        if f <= 80 {
            r = 32fx * (f as fx) / 80fx;
        }
        if f == 160 {
            ang = aim_player();                 // moveVel(%ANGLE_PLAYER, 0)
        }
        if f > 160 && f <= 280 {
            spd = (f - 160) as fx / 120fx;      // moveSpeedTime mode0 -> 1.0
        }
        ax = ax + spd * cos(ang);
        ay = ay + spd * sin(ang);
        move_to(0, ax + r * cos(theta), ay + r * sin(theta), EASE_LINEAR);
        wait(1);
        f = f + 1;
    }
}

// ------------------------------------------------------------------ MainSub01
// Source 579-591: wait 60, then 3x enmCreate Phantom02 at
// (-144 + RANDF2*32, 128 + RANDF2*32), wait 60. Two RANDF2 draws per enemy (x, y).
async sub mainsub01() {
    wait(60);
    var i: int = 0;
    while i < 3 {
        var ux: fx = ((rand(65536) - 32768) as fx) / (32768 as fx);
        var uy: fx = ((rand(65536) - 32768) as fx) / (32768 as fx);
        _ = spawn_enemy(-144fx + 32fx * ux, 128fx + 32fx * uy, 170, 0, 1000, 0, phantom02);
        wait(60);
        i = i + 1;
    }
}

// ------------------------------------------------------------------ MainSub00
// Source 564-577: wait 120, @MainSub01 async, then 20x enmCreate Phantom01 at
// the caller-relative (192,144), hp 170, score 1000, every 15 frames.
// The stage caller sits at the world origin, so the relative offsets are used as
// absolute spawn coordinates.
async sub mainsub00() {
    wait(120);
    spawn mainsub01();
    var i: int = 0;
    while i < 20 {
        _ = spawn_enemy(192fx, 144fx, 170, 0, 1000, 0, phantom01);
        wait(15);
        i = i + 1;
    }
}

// ---------------------------------------------------------------- card shell
async sub wave() {
    wait(OPENING_BUFFER);
    spawn mainsub00();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(1); }
}
